<?php require_once __DIR__.'/seguridad.php'; simceRequireRole(array('superadmin','administrador'),false); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Personalización</title><style>
*{box-sizing:border-box}body{margin:0;padding:24px;background:#f1f5f9;color:#172554;font-family:Arial,sans-serif}.card{max-width:760px;margin:auto;background:white;padding:28px;border-radius:18px;box-shadow:0 12px 40px #0f172a18}label{display:block;font-weight:700;margin-top:16px}input{width:100%;padding:12px;margin-top:6px;border:1px solid #94a3b8;border-radius:9px;font-size:16px}button{margin-top:22px;padding:13px 20px;border:0;border-radius:9px;background:#1d4ed8;color:white;font-weight:800;cursor:pointer}.preview{display:flex;align-items:center;gap:16px;padding:18px;margin-top:20px;background:#eff6ff;border-radius:12px}.preview img{width:80px;height:80px;object-fit:contain;background:white;border-radius:10px}.msg{font-weight:700;margin-top:14px}a{color:#1d4ed8}</style></head><body><main class="card"><p><a href="pruebas_educativas.php">← Volver al panel docente</a></p><h1>Personalización de la plataforma</h1><p>Estos datos aparecerán en la portada, el menú de pruebas y el panel docente.</p><form id="form"><label>Nombre de la plataforma<input name="nombre_plataforma" maxlength="80" required></label><label>Nombre del establecimiento<input name="nombre_establecimiento" maxlength="120" required></label><label>Subtítulo institucional<input name="subtitulo" maxlength="120" required></label><label>Saludo de la portada<input name="saludo" maxlength="120" required></label><label>Texto para elegir perfil<input name="seleccion_perfil" maxlength="100" required></label><label>Logo institucional (PNG, JPG, WebP o SVG; máximo 2 MB)<input name="logo" type="file" accept=".png,.jpg,.jpeg,.webp,.svg,image/*"></label><div class="preview"><img id="logoPreview" alt="Vista previa"><div><strong id="namePreview"></strong><div id="institutionPreview"></div></div></div><button>Guardar personalización</button><div id="message" class="msg" role="status"></div></form></main><script src="sesion-cliente.js"></script><script>
const form=document.querySelector('#form'),message=document.querySelector('#message'),logoPreview=document.querySelector('#logoPreview'),namePreview=document.querySelector('#namePreview'),institutionPreview=document.querySelector('#institutionPreview');function show(m){Object.keys(m).forEach(k=>{if(form.elements[k]&&k!=='logo')form.elements[k].value=m[k]});logoPreview.src=m.logo;namePreview.textContent=m.nombre_plataforma;institutionPreview.textContent=m.nombre_establecimiento+' — '+m.subtitulo}fetch('personalizacion_api.php').then(r=>r.json()).then(x=>show(x.marca));form.logo.onchange=()=>{const f=form.logo.files[0];if(f)logoPreview.src=URL.createObjectURL(f)};form.oninput=()=>{namePreview.textContent=form.nombre_plataforma.value;institutionPreview.textContent=form.nombre_establecimiento.value+' — '+form.subtitulo.value};form.onsubmit=async e=>{e.preventDefault();message.textContent='Guardando…';const r=await window.simceAuthenticatedFetch('personalizacion_api.php',{method:'POST',body:new FormData(form)});const x=await r.json();message.textContent=x.ok?'Personalización guardada correctamente.':x.error;if(x.ok)show(x.marca)};
</script></body></html>
